CREATE TABLE teams(id BIGSERIAL PRIMARY KEY,owner_id BIGINT NOT NULL REFERENCES app_users(id),title VARCHAR(200) NOT NULL,content TEXT NOT NULL,roles VARCHAR(1000) NOT NULL,tags VARCHAR(500),capacity INTEGER NOT NULL CHECK(capacity BETWEEN 2 AND 100),deadline TIMESTAMPTZ NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('OPEN','CLOSED','COMPLETED')));
CREATE TABLE team_applications(id BIGSERIAL PRIMARY KEY,team_id BIGINT NOT NULL REFERENCES teams(id),user_id BIGINT NOT NULL REFERENCES app_users(id),role VARCHAR(100) NOT NULL,message TEXT NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','ACCEPTED','REJECTED','CANCELLED')),updated_at TIMESTAMPTZ NOT NULL,UNIQUE(team_id,user_id));
CREATE TABLE team_entries(id BIGSERIAL PRIMARY KEY,team_id BIGINT NOT NULL REFERENCES teams(id),kind VARCHAR(20) NOT NULL CHECK(kind IN ('MEETING','DEADLINE','TASK','STAGE','LINK')),title VARCHAR(200) NOT NULL,content TEXT,assignee_id BIGINT REFERENCES app_users(id),starts_at TIMESTAMPTZ,ends_at TIMESTAMPTZ,url VARCHAR(2000),done BOOLEAN NOT NULL DEFAULT false);
